// 18: interface polymorphism — a trait used as a type dispatches to different structs
#include <stdio.h>

struct Greeter_vtbl {
    void (*greet)(void *);
};
struct Greeter_iface {
    void *self;
    struct Greeter_vtbl *vt;
};


struct Person {
    char *name;
    struct Greeter_vtbl *__greeter_vptr;
};


struct Shop {
    char *name;
    struct Greeter_vtbl *__greeter_vptr;
};


static void Person_Greeter_greet(void *self) {
    struct Person *_self = (struct Person *)self;
    printf("hi %s\n", _self->name);
}

static struct Greeter_vtbl Person_Greeter_vtable = {
    .greet = Person_Greeter_greet
};



static void Shop_Greeter_greet(void *self) {
    struct Shop *_self = (struct Shop *)self;
    printf("shop %s\n", _self->name);
}

static struct Greeter_vtbl Shop_Greeter_vtable = {
    .greet = Shop_Greeter_greet
};



void announce(struct Greeter_iface who) {
    who.vt->greet(who.self);
}

struct Greeter_iface pick(struct Person *p, struct Shop *s, int which) {
    if (which) {
        return (struct Greeter_iface){ (void *)p, &Person_Greeter_vtable };
    }
    return (struct Greeter_iface){ (void *)s, &Shop_Greeter_vtable };
}

int main(void) {
    struct Person p = { .name = "Tom", .__greeter_vptr = &Person_Greeter_vtable };
    struct Shop s = { .name = "Mart", .__greeter_vptr = &Shop_Greeter_vtable };

    announce((struct Greeter_iface){ (void *)&p, &Person_Greeter_vtable });
    announce((struct Greeter_iface){ (void *)&s, &Shop_Greeter_vtable });

    struct Greeter_iface g = (struct Greeter_iface){ (void *)&p, &Person_Greeter_vtable };
    g.vt->greet(g.self);
    g = (struct Greeter_iface){ (void *)&s, &Shop_Greeter_vtable };
    g.vt->greet(g.self);

    struct Greeter_iface h = pick(&p, &s, 1);
    h.vt->greet(h.self);
    return 0;
}
